/**
 * ProductList Component Tests
 *
 * Tests for the products page list rendering, filtering, and display logic.
 * This file tests the product list display, empty states, loading states,
 * error handling, and filtering functionality.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import {
  createMockProduct,
  createMockCategory,
  createMockCurrentPrice,
  createMockProducts,
} from '@/__tests__/fixtures/test-data'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
import ProductsPage from '../page'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('ProductList', () => {
  const mockOrganizationId = 'test-org-id'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Product List Rendering', () => {
    it('renders product list correctly with products', async () => {
      // Arrange
      const mockProducts = [
        createMockProduct({
          id: 'prod-1',
          name: 'Izgara Kofte',
          description: 'Delicious grilled meatballs',
          category_id: 'cat-1',
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockProduct({
          id: 'prod-2',
          name: 'Adana Kebab',
          description: 'Spicy minced meat kebab',
          category_id: 'cat-1',
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Main Dishes',
          organization_id: mockOrganizationId,
        }),
      ]

      const mockPrices = [
        createMockCurrentPrice({ product_id: 'prod-1', price: 45.5, currency: 'TRY' }),
        createMockCurrentPrice({ product_id: 'prod-2', price: 52.0, currency: 'TRY' }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      // Setup mock responses for different queries
      const fromMock = vi.fn((table: string) => {
        if (table === 'products') {
          return createMockQueryBuilder({ selectData: mockProducts })
        }
        if (table === 'current_prices') {
          return createMockQueryBuilder({ selectData: mockPrices })
        }
        if (table === 'categories') {
          return createMockQueryBuilder({ selectData: mockCategories })
        }
        return createMockQueryBuilder({ selectData: [] })
      })

      mockClient.from = fromMock as any

      // Helper to create a proper query builder
      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          in: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<ProductsPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Izgara Kofte')).toBeInTheDocument()
      })

      expect(screen.getByText('Adana Kebab')).toBeInTheDocument()
      expect(screen.getByText('Delicious grilled meatballs')).toBeInTheDocument()
      expect(screen.getByText('Main Dishes')).toBeInTheDocument()
      expect(screen.getByText('₺45,50')).toBeInTheDocument()
      expect(screen.getByText('₺52,00')).toBeInTheDocument()
    })

    it('displays product with allergens badge', async () => {
      // Arrange
      const mockProducts = [
        createMockProduct({
          id: 'prod-1',
          name: 'Pasta Carbonara',
          allergens: ['Gluten', 'Eggs', 'Dairy'],
