        expect(screen.getByText('Hidden Product')).toBeInTheDocument()
      })

      // Find the parent container with opacity class
      const productElement = screen.getByText('Hidden Product').closest('div')
      expect(productElement?.className).toMatch(/opacity-60/)
    })
  })

  describe('Empty State', () => {
    it('displays empty state when no products exist', async () => {
