  describe('Category Filtering', () => {
    it('filters products by selected category', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Main Dishes',
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-2',
